css:
.loader {
  display: flex;
  justify-content: center;
  align-items: center;
}

.container {
  overflow: visible;
}

/* Road */
.road {
  stroke: #d0d0d0;
  stroke-width: 2.5;
  stroke-linecap: round;
}

.road-lines {
  stroke: #666;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-dasharray: 10 18;
  animation: roadMove 0.8s linear infinite;
}

/* Car */
.car {
  animation: carMove 1.8s ease-in-out infinite;
}

.car-body {
  fill: none;
  stroke: #4f8cff;
  stroke-width: 2.5;
  stroke-linejoin: round;
}

.window {
  fill: #d0d0d0;
  stroke: #4f8cff;
  stroke-width: 1.5;
}

.light {
  fill: #4f8cff;
  animation: lightBlink 1s ease-in-out infinite;
}

/* Wheels */
.wheel {
  fill: #666;
  stroke: #4f8cff;
  stroke-width: 2;
  transform-box: fill-box;
  transform-origin: center;
  animation: wheelSpin 0.6s linear infinite;
}

.hub {
  fill: #d0d0d0;
  stroke: none;
}

/* Speed lines */
.speed-lines {
  stroke: #4f8cff;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-dasharray: 8 12;
  animation: speedMove 0.7s linear infinite;
}

/* Road animation */
@keyframes roadMove {
  from {
    stroke-dashoffset: 0;
  }

  to {
    stroke-dashoffset: -28;
  }
}

/* Car movement */
@keyframes carMove {
  0%,
  100% {
    transform: translateX(0);
  }

  50% {
    transform: translateX(5px);
  }
}

/* Wheel rotation */
@keyframes wheelSpin {
  from {
    transform: rotate(0deg);
  }

  to {
    transform: rotate(360deg);
  }
}

/* Headlight */
@keyframes lightBlink {
  0%,
  100% {
    opacity: 0.4;
  }

  50% {
    opacity: 1;
  }
}

/* Speed lines */
@keyframes speedMove {
  from {
    stroke-dashoffset: 0;
    opacity: 0.3;
  }

  to {
    stroke-dashoffset: -20;
    opacity: 1;
  }
}
